const staticData = $getWorkflowStaticData('global');
const sentIds = staticData.sentIds || [];

// 取得 PubMed 的結果
// 請確保 ['HTTP Request1'] 的名稱與你抓取詳情的節點名稱一致
const allArticles = Object.values($node["Article Title"].json.result).filter(i => i.uid);

// 1. 過濾掉重複的 ID
const newArticles = allArticles.filter(article => !sentIds.includes(article.uid));

// 2. 只取前 5 篇
const articlesToSend = newArticles.slice(0, 5);

// 如果沒有新文章，就停止工作流，不發送訊息
if (articlesToSend.length === 0) {
  return []; 
}

// 3. 更新靜態資料 (去重記錄)
const newSentIds = [...sentIds, ...articlesToSend.map(a => a.uid)].slice(-1000);
staticData.sentIds = newSentIds;

// 4. 【核心步驟】將 5 篇文章整合為一個字串
let combinedMessage = "📖 今日視覺研究推薦：\n\n";

articlesToSend.forEach((a, index) => {
  combinedMessage += `${index + 1}. **${a.title}**\n🔗 https://pubmed.ncbi.nlm.nih.gov/${a.uid}/\n\n`;
});

// 5. 只回傳一個項目給下一個節點
return [{
  json: {
    message: combinedMessage
  }
}];
